//! 🪆️ Logical Record owners retain arbitrary schema and octets while raw PNG publication refuses invalid files.
use super::*;
#[test]
fn sqlite_snapshot_png_logical_owner_retains_literal_schema_and_arbitrary_octets(){
 use store::{ArtifactDsl,ArtifactPack,ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteSnapshotControl,SnapshotEncoding}};
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../🚪️io/🪶️sqlite/📸️snapshot/🧫️fixtures/🪆️owner/🔣️.json")).unwrap();
 for case in corpus["cases"].as_array().unwrap(){let snapshot=PngSnapshot{schema:case["schema"].as_str().unwrap().into(),bytes:case["bytes"].as_array().unwrap().iter().map(|byte|u8::try_from(byte.as_u64().unwrap()).unwrap()).collect()};assert!(crate::standards::v1_2::subsets::any::io::encode_png(&snapshot).is_err(),"raw PNG publication must retain its own validators");assert_eq!(PngSnapshot::parse_dsl(&snapshot.print_dsl()).unwrap(),snapshot);let packed=snapshot.encode_pack_with(&Default::default()).unwrap();assert_eq!(PngSnapshot::decode_pack_with(&packed,&Default::default()).unwrap(),snapshot);let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();assert_eq!(database.table("png_document").unwrap().single_row().unwrap().text(2).unwrap(),"literal");assert_eq!(database.table("png_literal_octet").unwrap().rows.len(),snapshot.bytes.len());assert_eq!(PngSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap(),snapshot);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();let restored=PngSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();assert_eq!(restored,snapshot);}}
}
